using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Collections.Generic;using System.Text.Json;using System.Text.Json.Nodes;
namespace BF4Launcher;
public static class GroupedModTests {
 public static void Run(Action<bool,string> check){var root=Path.Combine(Path.GetTempPath(),"BF4-GroupedMods-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(root,"engine"));File.WriteAllText(Path.Combine(root,"engine/server-fields.json"),"[{\"id\":\"value\",\"label\":\"数值\",\"type\":\"number\",\"min\":0,\"max\":10,\"defaultValue\":1}]");
 ModItem Item(string id,string version,int amount,bool enabled){var manifest=new ModManifest{Id=id,Name=id,Version=version,Side="server",Fields=new(){new FieldDef{Id="value",Label="倍率",Type="number",Min=0,Max=10,DefaultValue=JsonValue.Create(1)}},Operations=new(){new Operation{Field="value",Value=JsonValue.Create("$value")}}};var item=new ModItem{Key=id+"@"+version,Directory=Path.Combine("mods",id,version),Manifest=manifest,Enabled=enabled,Config=new(){["value"]=JsonValue.Create(amount)}};var path=Path.Combine(root,item.Directory);Directory.CreateDirectory(path);Repository.Atomic(Path.Combine(path,"mod.json"),JsonSerializer.Serialize(manifest,Repository.Json));return item;}
 var a=Item("first","1.0.0",2,true);var other=Item("second","1.0.0",5,true);var b=Item("first","2.0.0",7,true);var legacy=new LauncherConfig{SchemaVersion=1,Rotation=new(){new RotationEntry()},Server=new(){["value"]=JsonValue.Create(1)}};legacy.Mods.Add(a);legacy.Mods.Add(other);legacy.Mods.Add(b);string aFile=Path.Combine(root,a.Directory,"config.json"),bFile=Path.Combine(root,b.Directory,"config.json");File.WriteAllText(aFile,"{\"value\":3,\"internal\":42}");File.WriteAllText(bFile,"{ \"value\":8 }");Repository.Atomic(Path.Combine(root,"config.json"),JsonSerializer.Serialize(legacy,Repository.Json));
 var repo=new Repository(root);repo.Load();a=repo.Config.Mods.Single(m=>m.Key==a.Key);b=repo.Config.Mods.Single(m=>m.Key==b.Key);check(repo.Config.SchemaVersion==2,"groups-schema-upgraded");check(JsonNode.Parse(File.ReadAllText(repo.ConfigPath))!["schemaVersion"]!.GetValue<int>()==2,"groups-migration-persisted-before-runtime-start");check(Directory.GetFiles(Path.Combine(root,"data/migrations"),"config-before-mod-groups-*.json").Length==1,"groups-original-config-backed-up");check(repo.ModCards.Count==2&&repo.VersionsOf("first").Count==2,"groups-one-card-per-id");check(repo.ModCards.Single(m=>m.Manifest.Id=="first").Version=="2.0.0","groups-migration-keeps-last-effective-version-not-highest-rule");check(repo.Config.Mods.Count(m=>m.Manifest.Id=="first"&&m.Enabled)==1,"groups-only-selected-version-enabled");check(repo.Config.ModGroups!.Select(g=>g.Id).SequenceEqual(new[]{"second","first"}),"groups-effective-priority-preserved");check(a.Config["value"]!.GetValue<int>()==3&&b.Config["value"]!.GetValue<int>()==8,"groups-version-files-authoritative");string rawA=File.ReadAllText(aFile),rawB=File.ReadAllText(bFile);repo.Save();check(File.ReadAllText(aFile)==rawA&&File.ReadAllText(bFile)==rawB,"groups-unedited-version-files-not-rewritten");
 repo.SelectModVersion("first","1.0.0");check(a.Enabled&&!b.Enabled,"groups-version-switch-transfers-group-enabled-state");a.Config["value"]=JsonValue.Create(4);repo.SaveModVersion(a);check(JsonNode.Parse(File.ReadAllText(aFile))!["value"]!.GetValue<int>()==4,"groups-edit-writes-current-version");check(JsonNode.Parse(File.ReadAllText(aFile))!["internal"]!.GetValue<int>()==42,"groups-unexposed-parameters-preserved");check(File.ReadAllText(bFile)==rawB,"groups-edit-does-not-touch-other-version");repo.SelectModVersion("first","2.0.0");check(repo.Plan().Values["value"]!.GetValue<int>()==8,"groups-selected-version-only-affects-plan");repo.SetModEnabled("first",false);repo.SelectModVersion("first","1.0.0");check(!a.Enabled&&!b.Enabled,"groups-disabled-state-survives-switch");repo.SelectModVersion("first","2.0.0");repo.MoveMod("first",0);check(repo.Config.ModGroups![0].Id=="first"&&repo.Config.Mods.Take(2).All(m=>m.Manifest.Id=="first"),"groups-order-moves-entire-mod-not-a-version");
 var package=Path.Combine(root,"version3.zip");using(var z=ZipFile.Open(package,ZipArchiveMode.Create)){using(var w=new StreamWriter(z.CreateEntry("mod.json").Open()))w.Write(JsonSerializer.Serialize(new ModManifest{Id="first",Name="first",Version="3.0.0",Fields=b.Manifest.Fields,Operations=b.Manifest.Operations,Side="server"},Repository.Json));using(var w=new StreamWriter(z.CreateEntry("config.json").Open()))w.Write("{\"value\":9}");}repo.Import(package);check(repo.ModCards.Count==2&&repo.VersionsOf("first").Count==3,"groups-import-adds-choice-not-card");check(repo.ModCards.Single(m=>m.Manifest.Id=="first").Version=="2.0.0"&&!repo.ModCards.Single(m=>m.Manifest.Id=="first").Enabled,"groups-import-does-not-switch-or-enable");
 var reload=new Repository(root);reload.Load();check(reload.ModCards.Single(m=>m.Manifest.Id=="first").Version=="2.0.0"&&reload.Config.ModGroups![0].Id=="first","groups-selection-and-priority-reload");check(reload.Config.Mods.Single(m=>m.Key==a.Key).Config["value"]!.GetValue<int>()==4&&reload.Config.Mods.Single(m=>m.Key==b.Key).Config["value"]!.GetValue<int>()==8,"groups-independent-settings-reload");var selected=reload.ModCards.Single(m=>m.Manifest.Id=="first");reload.RemoveModVersion(selected);check(reload.VersionsOf("first").Count==2&&Directory.Exists(Path.Combine(root,a.Directory)),"groups-uninstall-only-selected-version");check(!reload.ModCards.Single(m=>m.Manifest.Id=="first").Enabled,"groups-removing-selected-version-does-not-auto-enable-other");
 var current=reload.ModCards.Single(m=>m.Manifest.Id=="first");string currentFile=Path.Combine(root,current.Directory,"config.json");File.WriteAllText(currentFile,"{\"value\":6}");current.Config["value"]=JsonValue.Create(7);bool blocked=false;try{reload.SaveModVersion(current);}catch{blocked=true;}check(blocked&&File.ReadAllText(currentFile)=="{\"value\":6}","groups-external-edit-conflict-does-not-overwrite");reload.RefreshModDirectory();
 string original=current.Directory;current.Directory="../outside";blocked=false;try{reload.RemoveModVersion(current);}catch{blocked=true;}current.Directory=original;check(blocked&&reload.Config.Mods.Contains(current),"groups-uninstall-validates-directory-before-changing-state");
 }
}
